#!/usr/bin/env python3
"""Single-file Google Colab bootstrap for OpenCode.

Run from a Colab notebook cell. Mounts Drive (with Google's approval prompt),
prepares OpenCode, restores sanitized session exports, and starts backups.
It deliberately does not launch the interactive TUI inside the notebook.
"""
from __future__ import annotations
import os
import subprocess
from pathlib import Path

SETUP_SCRIPT = '#!/usr/bin/env bash\n# OpenCode + Google Colab bootstrap\n# Run from a Colab notebook cell after Drive authorization, or from Colab Terminal.\n# This script restores global config + sanitized session exports, starts a\n# 60-second sanitized session exporter, then launches OpenCode.\nset -Eeuo pipefail\n\nDRIVE_ROOT="/content/drive/MyDrive/OpenCode"\nCONFIG_DIR="$DRIVE_ROOT/Environment"\nSESSIONS_DIR="$DRIVE_ROOT/Sessions/sanitized"\nBACKUP_DIR="$DRIVE_ROOT/Backups"\nPROJECTS_DIR="/content/projects"\nLOCAL_CONFIG="${XDG_CONFIG_HOME:-$HOME/.config}/opencode"\nLOCAL_DATA="${XDG_DATA_HOME:-$HOME/.local/share}/opencode"\nBIN_DIR="$HOME/.opencode/bin"\nOPENCODE="$BIN_DIR/opencode"\nINTERVAL=60\n\nlog(){ printf \'\\n[%s] %s\\n\' "$(date \'+%H:%M:%S\')" "$*"; }\nneed(){ command -v "$1" >/dev/null 2>&1 || { echo "Missing dependency: $1"; exit 1; }; }\n\n# Drive is mounted by the companion Python bootstrap, which runs inside Colab.\nif [[ ! -d /content/drive/MyDrive ]]; then\n  cat <<\'EOF\'\nGoogle Drive is not mounted.\nRun the Colab Python cell that calls:\n    from google.colab import drive\n    drive.mount(\'/content/drive\')\nThen rerun this launcher.\nEOF\n  exit 2\nfi\n\nneed curl\nneed python3\nneed git\n\nmkdir -p "$CONFIG_DIR" "$SESSIONS_DIR" "$BACKUP_DIR" "$PROJECTS_DIR" \\\n         "$DRIVE_ROOT/Runtime" "$DRIVE_ROOT/Environment/agents" \\\n         "$DRIVE_ROOT/Environment/skills" "$DRIVE_ROOT/Environment/commands" \\\n         "$DRIVE_ROOT/Environment/plugins" "$DRIVE_ROOT/Environment/mcp"\n\nlog "Installing OpenCode (if needed)"\nif [[ ! -x "$OPENCODE" ]]; then\n  curl -fsSL https://opencode.ai/v2/install | bash\nfi\nif [[ ! -x "$OPENCODE" ]]; then\n  FOUND="$(command -v opencode || true)"\n  if [[ -n "$FOUND" ]]; then OPENCODE="$FOUND"; fi\nfi\n[[ -x "$OPENCODE" ]] || { echo "OpenCode binary not found after install."; exit 3; }\nexport PATH="$(dirname "$OPENCODE"):$PATH"\n# Make `opencode` available in fresh Colab Terminal shells as well.\nmkdir -p /usr/local/bin\nln -sf "$OPENCODE" /usr/local/bin/opencode\nif ! printf \'%s\' ":$PATH:" | grep -q \':/usr/local/bin:\'; then\n  grep -qxF \'export PATH="/usr/local/bin:$PATH"\' "$HOME/.bashrc" 2>/dev/null || \\\n    printf \'\\nexport PATH="/usr/local/bin:$PATH"\\n\' >> "$HOME/.bashrc"\nfi\n"$OPENCODE" --version\n\nlog "Preparing global configuration"\nmkdir -p "$(dirname "$LOCAL_CONFIG")"\n# One-time migration of existing local config to Drive, without overwriting Drive files.\nif [[ -d "$LOCAL_CONFIG" && ! -L "$LOCAL_CONFIG" ]]; then\n  cp -an "$LOCAL_CONFIG/." "$CONFIG_DIR/"\n  mv "$LOCAL_CONFIG" "${LOCAL_CONFIG}.pre-drive.$(date +%s)"\nfi\nif [[ -L "$LOCAL_CONFIG" ]]; then rm "$LOCAL_CONFIG"; fi\nln -s "$CONFIG_DIR" "$LOCAL_CONFIG"\n\n# Create a safe default AGENTS.md if none exists.\nif [[ ! -f "$CONFIG_DIR/AGENTS.md" ]]; then\ncat > "$CONFIG_DIR/AGENTS.md" <<\'EOF\'\n# Personal OpenCode instructions\n\n- Explain significant changes before making broad edits.\n- Prefer maintainable implementations and run relevant tests.\n- Never write API keys, passwords, OAuth tokens, or private credentials into files.\nEOF\nfi\n\nlog "Restoring sanitized sessions into the local OpenCode store"\nmkdir -p "$LOCAL_DATA"\n# Session import is performed from each JSON export. Import errors are logged,\n# not fatal: an export may belong to a newer/different OpenCode version.\nRESTORE_LOG="$DRIVE_ROOT/Runtime/restore-$(date +%Y%m%d-%H%M%S).log"\npython3 - "$OPENCODE" "$SESSIONS_DIR" "$RESTORE_LOG" <<\'PYRESTORE\'\nimport json, pathlib, subprocess, sys\nbinary, folder, logpath = sys.argv[1:]\nfolder = pathlib.Path(folder)\ndef log(s):\n    with open(logpath, "a", encoding="utf-8") as f: f.write(s + "\\n")\ndef ids(value):\n    out = set()\n    def walk(x):\n        if isinstance(x, dict):\n            sid = x.get("id")\n            if isinstance(sid, str) and sid.startswith("ses_"): out.add(sid)\n            for v in x.values(): walk(v)\n        elif isinstance(x, list):\n            for v in x: walk(v)\n    walk(value)\n    return out\ntry:\n    p = subprocess.run([binary, "session", "list", "--format", "json"],\n                       capture_output=True, text=True, timeout=90)\n    current = ids(json.loads(p.stdout or "[]")) if p.returncode == 0 else set()\nexcept Exception:\n    current = set()\nfor file in sorted(folder.glob("*.json")):\n    try:\n        exported = json.loads(file.read_text(encoding="utf-8"))\n        exported_ids = ids(exported)\n        if exported_ids and exported_ids.issubset(current):\n            log("already present; skipped " + file.name)\n            continue\n        result = subprocess.run([binary, "session", "import", str(file)],\n                                capture_output=True, text=True, timeout=120)\n        if result.returncode:\n            log("IMPORT FAILED " + file.name + ": " + result.stderr[-700:])\n        else:\n            current |= exported_ids\n            log("imported " + file.name)\n    except Exception as exc:\n        log("RESTORE ERROR " + file.name + ": " + repr(exc))\nPYRESTORE\n\nlog "Creating the 60-second session backup worker"\ncat > /content/opencode-session-backup.py <<\'PY\'\nimport json, os, re, subprocess, time, tempfile\nfrom pathlib import Path\n\nOPENCODE = os.environ["OPENCODE_BIN"]\nDEST = Path(os.environ["OPENCODE_SESSIONS_DIR"])\nLOG = Path(os.environ["OPENCODE_BACKUP_LOG"])\nINTERVAL = int(os.environ.get("OPENCODE_BACKUP_INTERVAL", "60"))\nDEST.mkdir(parents=True, exist_ok=True)\nLOG.parent.mkdir(parents=True, exist_ok=True)\n\ndef log(msg):\n    with LOG.open("a", encoding="utf-8") as f:\n        f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + msg + "\\n")\n\ndef main():\n    log("session exporter started")\n    while True:\n        try:\n            p = subprocess.run(\n                [OPENCODE, "session", "list", "--format", "json"],\n                capture_output=True, text=True, timeout=90\n            )\n            if p.returncode:\n                raise RuntimeError("session list: " + p.stderr[-700:])\n            data = json.loads(p.stdout or "[]")\n            # Current CLI emits a list of session objects.\n            if isinstance(data, dict):\n                data = data.get("sessions", data.get("data", []))\n            for item in data if isinstance(data, list) else []:\n                sid = item.get("id", "") if isinstance(item, dict) else ""\n                if not re.fullmatch(r"ses_[A-Za-z0-9_-]+", sid):\n                    continue\n                # Export in the session\'s project directory where possible.\n                cmd = [OPENCODE, "session", "export", sid, "--sanitize"]\n                cwd = item.get("directory") if isinstance(item, dict) else None\n                exp = subprocess.run(cmd, cwd=cwd or None, capture_output=True,\n                                     text=True, timeout=120)\n                if exp.returncode:\n                    log(f"export failed {sid}: {exp.stderr[-500:]}")\n                    continue\n                try:\n                    json.loads(exp.stdout)\n                    target = DEST / (sid + ".json")\n                    fd, tmp = tempfile.mkstemp(prefix=sid, suffix=".tmp", dir=DEST)\n                    with os.fdopen(fd, "w", encoding="utf-8") as out:\n                        out.write(exp.stdout)\n                        out.flush()\n                        os.fsync(out.fileno())\n                    os.replace(tmp, target)\n                    log("saved sanitized export " + sid)\n                except Exception as e:\n                    log(f"invalid export {sid}: {e}")\n        except Exception as e:\n            log("backup cycle error: " + repr(e))\n        time.sleep(INTERVAL)\n\nif __name__ == "__main__":\n    main()\nPY\n\n# Stop previous worker if this launcher is run again in same runtime.\nPIDFILE="/content/opencode-session-backup.pid"\nif [[ -f "$PIDFILE" ]]; then\n  OLD_PID="$(cat "$PIDFILE" || true)"\n  if [[ "$OLD_PID" =~ ^[0-9]+$ ]] && kill -0 "$OLD_PID" 2>/dev/null; then\n    kill "$OLD_PID" 2>/dev/null || true\n  fi\nfi\n\nexport OPENCODE_BIN="$OPENCODE"\nexport OPENCODE_SESSIONS_DIR="$SESSIONS_DIR"\nexport OPENCODE_BACKUP_LOG="$DRIVE_ROOT/Runtime/session-backup.log"\nexport OPENCODE_BACKUP_INTERVAL="$INTERVAL"\nnohup python3 /content/opencode-session-backup.py \\\n  >/content/opencode-session-backup.out 2>&1 </dev/null &\necho $! > "$PIDFILE"\n\nlog "Preparing workspace"\nmkdir -p "$PROJECTS_DIR"\ncd "$PROJECTS_DIR"\n\ncat <<EOF\n\n============================================================\nOpenCode is ready.\nGlobal config:   $CONFIG_DIR\nSession exports:$SESSIONS_DIR\nProjects:        $PROJECTS_DIR\nBackup interval: ${INTERVAL}s (sanitized JSON exports)\nBackup log:      $DRIVE_ROOT/Runtime/session-backup.log\n\nOpenCode is prepared. In Colab Terminal, type: opencode\nUse /sessions to browse imported sessions.\nTo work on a GitHub project, ask OpenCode to clone its repository.\n============================================================\n\nEOF\n\n# Notebook-driven setup uses this mode so the TUI is launched later from\n# Colab Terminal, which provides an interactive terminal (TTY).\nif [[ "${OPENCODE_SETUP_ONLY:-0}" == "1" ]]; then\n  log "Setup complete. In Colab Terminal, run: opencode"\n  exit 0\nfi\n\nexec "$OPENCODE"\n'

def main() -> None:
    try:
        from google.colab import drive
    except ImportError as exc:
        raise SystemExit("Run this bootstrap from a Google Colab notebook cell.") from exc

    print("[1/2] Mounting Google Drive. Approve Google's prompt if it appears...", flush=True)
    drive.mount("/content/drive", force_remount=False)
    if not Path("/content/drive/MyDrive").is_dir():
        raise SystemExit("Google Drive mount did not complete.")

    print("[2/2] Preparing OpenCode, restoring sessions, and starting backups...", flush=True)
    setup_path = Path("/content/opencode_colab_setup.sh")
    setup_path.write_text(SETUP_SCRIPT, encoding="utf-8")
    setup_path.chmod(0o700)
    env = os.environ.copy()
    env["OPENCODE_SETUP_ONLY"] = "1"
    subprocess.run(["bash", str(setup_path)], check=True, env=env)

    print("\nSETUP COMPLETE", flush=True)
    print("Open Colab Terminal and type: opencode", flush=True)
    print("Projects workspace: /content/projects", flush=True)
    print("OpenCode config and sanitized session backups: MyDrive/OpenCode", flush=True)

if __name__ == "__main__":
    main()
